export interface StSaintTab {
  id: string;
  title: string;
  titleAr: string;
  // In Spirit & Truth's order; a hymn without a saint is sung for every saint
  hymns: Hymn[];
  saintOf: Record<string, string>;
  titlesAr: Record<string, string>;
}

